import difflib
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from reversion.models import Version
from .models import LegalAgreement

class LegalAgreementDiffView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, agreement_id):
        from_version_id = request.query_params.get('from_version')
        to_version_id = request.query_params.get('to_version')

        # Ensure the user has access to the target legal agreement first
        try:
            agreement = LegalAgreement.objects.get(pk=agreement_id, organization=request.user.organization)
        except LegalAgreement.DoesNotExist:
            return Response({'error': 'Agreement not found or access denied'}, status=status.HTTP_404_NOT_FOUND)

        # Scope version lookups to the verified agreement instance
        try:
            v_from = Version.objects.get_for_object(agreement).get(pk=from_version_id)
            v_to = Version.objects.get_for_object(agreement).get(pk=to_version_id)
        except Version.DoesNotExist:
            return Response({'error': 'Specified version not found for this agreement'}, status=status.HTTP_404_NOT_FOUND)

        text_from = v_from.field_dict.get('terms_content', '').splitlines(keepends=True)
        text_to = v_to.field_dict.get('terms_content', '').splitlines(keepends=True)
        diff = list(difflib.unified_diff(text_from, text_to, fromfile='baseline', tofile='current'))
        return Response({'diff': diff})
